package com.xauusdpro99.notification;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.database.*;import android.database.sqlite.*;import android.os.Build;import com.xauusdpro99.MainActivity;import java.util.*;
/** Local SQLite notification history and Android channel delivery. */
public final class NotificationCenter extends SQLiteOpenHelper{
 public static final String CHANNEL_ID="xauusd_market_alerts";private static final String DB="xauusd_notifications.db";
 public static final class Item{public final long id,timestampMs;public final String title,message;public final boolean read;Item(long i,long t,String a,String b,boolean r){id=i;timestampMs=t;title=a;message=b;read=r;}}
 public NotificationCenter(Context c){super(c.getApplicationContext(),DB,null,1);createChannel(c.getApplicationContext());}
 @Override public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE notifications (_id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,message TEXT NOT NULL,event_time INTEGER NOT NULL,is_read INTEGER NOT NULL DEFAULT 0)");db.execSQL("CREATE INDEX idx_notifications_time ON notifications(event_time DESC)");}
 @Override public void onUpgrade(SQLiteDatabase db,int oldV,int newV){}
 private static void createChannel(Context c){if(Build.VERSION.SDK_INT>=26){NotificationManager m=c.getSystemService(NotificationManager.class);if(m!=null&&m.getNotificationChannel(CHANNEL_ID)==null){NotificationChannel ch=new NotificationChannel(CHANNEL_ID,"XAUUSD Market Alerts",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("Pemberitahuan peristiwa pasar XAUUSD");ch.setSound(null,null);m.createNotificationChannel(ch);}}}
 public long record(String title,String message,long ts){ContentValues v=new ContentValues();v.put("title",title);v.put("message",message);v.put("event_time",ts);return getWritableDatabase().insert("notifications",null,v);}
 public void show(Context c,long id,String title,String message){if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;NotificationManager m=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(m==null)return;Intent i=new Intent(c,MainActivity.class);i.setFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent p=PendingIntent.getActivity(c,(int)id,i,PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=23?PendingIntent.FLAG_IMMUTABLE:0));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL_ID):new Notification.Builder(c);m.notify((int)(id&0x7fffffff),b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(title).setContentText(message).setStyle(new Notification.BigTextStyle().bigText(message)).setContentIntent(p).setAutoCancel(true).build());}
 public List<Item> recent(int limit){List<Item>x=new ArrayList<>();Cursor c=getReadableDatabase().query("notifications",new String[]{"_id","title","message","event_time","is_read"},null,null,null,null,"event_time DESC",Integer.toString(Math.max(1,Math.min(200,limit))));try{while(c.moveToNext())x.add(new Item(c.getLong(0),c.getLong(3),c.getString(1),c.getString(2),c.getInt(4)!=0));}finally{c.close();}return x;}
 public void markRead(long id){ContentValues v=new ContentValues();v.put("is_read",1);getWritableDatabase().update("notifications",v,"_id=?",new String[]{Long.toString(id)});}
 public void markAllRead(){ContentValues v=new ContentValues();v.put("is_read",1);getWritableDatabase().update("notifications",v,"is_read=0",null);}
 public void publishNewsAlert(Context c,String headline,String summary,long ts,boolean enabled){String title="NEWS ALERT — XAUUSD";long id=record(title,headline+" | "+summary,ts);if(enabled&&id>0)show(c,id,title,headline+" | "+summary);}
}